const SESSION_DAYS = Number(process.env.SESSION_DAYS || 7);
const COOKIE_SECURE = process.env.COOKIE_SECURE === 'true';
const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY || '';

type Principal = { type: 'STAFF' | 'CUSTOMER'; id: string; role?: string; email: string; fullName: string };
type Req = FastifyRequest & { params: any; principal?: Principal; sessionId?: string; csrf?: string };
declare module 'fastify' { interface FastifyRequest { principal?: Principal; sessionId?: string; csrf?: string } }

const rolePermissions: Record<string, string[]> = {
  SUPER_ADMIN: ['*'],
  ADMIN: ['customers:read','customers:write','services:read','services:write','services:migrate','routers:read','routers:write','routers:provision','servers:read','servers:write','servers:migrate','providers:read','providers:write','catalog:read','catalog:write','orders:read','orders:write','payments:read','payments:write','jobs:read','jobs:write','audit:read','secrets:reveal'],
  SUPPORT: ['customers:read','customers:write','services:read','services:suspend','services:resume','subscriptions:read','routers:read','orders:read','payments:read'],
  TECHNICIAN: ['customers:read','services:read','services:write','services:migrate','routers:read','routers:write','routers:provision','servers:read','servers:write','servers:migrate','providers:read','providers:write','secrets:reveal','jobs:read','jobs:write'],
  FINANCE: ['customers:read','subscriptions:read','orders:read','payments:read','payments:write','payments:refund','audit:read']
};

function sha(value: string) { return crypto.createHash('sha256').update(value).digest(); }
function randomToken(bytes = 32) { return crypto.randomBytes(bytes).toString('base64url'); }
function encryptSecret(value: string) {
  if (!ENCRYPTION_KEY) throw new Error('ENCRYPTION_KEY is required');
  const key = crypto.createHash('sha256').update(ENCRYPTION_KEY).digest();
  const iv = crypto.randomBytes(12); const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const ciphertext = Buffer.concat([cipher.update(value, 'utf8'), cipher.final()]);
  return Buffer.concat([iv, cipher.getAuthTag(), ciphertext]);
}
function decryptSecret(value: Buffer) {
  if (!ENCRYPTION_KEY) throw new Error('ENCRYPTION_KEY is required');
  const key = crypto.createHash('sha256').update(ENCRYPTION_KEY).digest();
  const iv = value.subarray(0, 12), tag = value.subarray(12, 28), data = value.subarray(28);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv); decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(data), decipher.final()]).toString('utf8');
}
function db<T extends QueryResultRow = any>(text: string, values: any[] = []) { return pool.query<T>(text, values); }
function requireCsrf(req: Req) {
  const token = req.headers['x-csrf-token'];
  if (!req.csrf || typeof token !== 'string' || token !== req.csrf) throw Object.assign(new Error('CSRF validation failed'), { statusCode: 403 });
}
function requirePermission(req: Req, permission: string) {
  if (!req.principal || req.principal.type !== 'STAFF') throw Object.assign(new Error('Authentication required'), { statusCode: 401 });
  const allowed = rolePermissions[req.principal.role || ''] || [];
  if (!allowed.includes('*') && !allowed.includes(permission)) throw Object.assign(new Error('Forbidden'), { statusCode: 403 });
}
async function audit(client: PoolClient, req: Req, action: string, entityType: string, entityId: string | null, metadata: object = {}, customerId: string | null = null) {
  await client.query('INSERT INTO audit_logs(actor_type,actor_id,action,entity_type,entity_id,customer_id,request_id,ip,metadata) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)', [req.principal?.type || 'SYSTEM', req.principal?.id || null, action, entityType, entityId, customerId, req.id, req.ip, metadata]);
}
async function issueToken(principalType: string, principalId: string, purpose: string, ttlMinutes: number) {
  const token = randomToken(32);
  await db('UPDATE auth_tokens SET used_at=now() WHERE principal_type=$1 AND principal_id=$2 AND purpose=$3 AND used_at IS NULL', [principalType, principalId, purpose]);
  await db('INSERT INTO auth_tokens(principal_type,principal_id,purpose,token_hash,expires_at) VALUES($1,$2,$3,$4,now()+make_interval(mins=>$5))', [principalType, principalId, purpose, sha(token), ttlMinutes]);
  return token;
}
async function consumeToken(token: string, purpose: string) {
  const r = await db(`SELECT id,principal_type,principal_id FROM auth_tokens WHERE purpose=$1 AND token_hash=$2 AND used_at IS NULL AND expires_at>now()`, [purpose, sha(token)]);
  if (!r.rowCount) throw Object.assign(new Error('Invalid or expired token'), { statusCode: 400 });
  await db('UPDATE auth_tokens SET used_at=now() WHERE id=$1 AND used_at IS NULL', [r.rows[0].id]);
  return r.rows[0];
}

async function seed() {
  await db(`INSERT INTO provider_instances(name,type,base_url,credentials_ref) VALUES($1,'MARZBAN',$2,'MARZBAN_ADMIN') ON CONFLICT(name) DO NOTHING`, ['Default Marzban', process.env.MARZBAN_BASE_URL || 'http://127.0.0.1:8000']);
  const cat = await db(`INSERT INTO config_categories(name,slug,description,protocol,router_compatible,status) VALUES('VLESS Basic','vless-basic','باقة VLESS قياسية','vless',true,'ACTIVE') ON CONFLICT(slug) DO UPDATE SET name=EXCLUDED.name RETURNING id`);
  if (cat.rows[0]) await db(`INSERT INTO config_plans(category_id,name,duration_days,price_minor,quota_bytes,status) VALUES($1,'30 يوم',30,15000,53687091200,'ACTIVE') ON CONFLICT(category_id,name) DO NOTHING`, [cat.rows[0].id]);
  await db(`INSERT INTO router_products(sku,name,model,price_minor,status) VALUES('CB-001','Cowboy Bebop Router','OpenWrt x86',125000,'ACTIVE') ON CONFLICT(sku) DO NOTHING`);
  const adminEmail = process.env.ADMIN_EMAIL, adminPassword = process.env.ADMIN_PASSWORD, totp = process.env.ADMIN_TOTP_SECRET;
  if (adminEmail && adminPassword) {
    const exists = await db('SELECT id FROM staff_users WHERE email=$1', [adminEmail]);
    if (!exists.rowCount) {
      if (!totp) throw new Error('ADMIN_TOTP_SECRET is required when bootstrapping the first staff account');
      const hash = await argon2.hash(adminPassword, { type: argon2.argon2id });
      await db('INSERT INTO staff_users(email,full_name,password_hash,role,totp_secret_enc,totp_enabled) VALUES($1,$2,$3,$4,$5,true)', [adminEmail, 'مسؤول المنصة', hash, 'SUPER_ADMIN', encryptSecret(totp)]);
    }
  }
}

async function authenticate(req: Req, _reply: FastifyReply) {
  const token = req.cookies?.cb_session; if (!token) return;
  const r = await db(`SELECT s.id,s.csrf_hash,s.principal_type,s.principal_id,CASE WHEN s.principal_type='STAFF' THEN st.email ELSE c.email END email,CASE WHEN s.principal_type='STAFF' THEN st.full_name ELSE c.full_name END full_name,st.role FROM auth_sessions s LEFT JOIN staff_users st ON s.principal_type='STAFF' AND st.id=s.principal_id LEFT JOIN customers c ON s.principal_type='CUSTOMER' AND c.id=s.principal_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now()`, [sha(token)]);
  if (!r.rowCount) return;
  const row = r.rows[0]; req.sessionId = row.id; req.csrf = Buffer.from(row.csrf_hash).toString('hex');
  req.principal = { type: row.principal_type, id: row.principal_id, role: row.role, email: row.email, fullName: row.full_name };
}
async function createSession(reply: FastifyReply, req: Req, principal: Principal) {
  const token = randomToken(), csrf = randomToken(24), expires = new Date(Date.now() + SESSION_DAYS * 86400000);
  await db('INSERT INTO auth_sessions(principal_type,principal_id,token_hash,csrf_hash,ip,user_agent,expires_at) VALUES($1,$2,$3,$4,$5,$6,$7)', [principal.type, principal.id, sha(token), sha(csrf), req.ip, req.headers['user-agent'] || '', expires]);
  reply.setCookie('cb_session', token, { httpOnly: true, secure: COOKIE_SECURE, sameSite: 'lax', path: '/', expires });
  reply.setCookie('cb_csrf', csrf, { httpOnly: false, secure: COOKIE_SECURE, sameSite: 'lax', path: '/', expires });
  return csrf;
}
function errorStatus(e: any) { return Number(e?.statusCode) || 500; }
function normalizeLandline(raw: string) { let value=String(raw||'').trim().replace(/[\s().-]/g,''); if(value.startsWith('+20')) value=value.slice(3); else if(value.startsWith('20')) value=value.slice(2); if(!value.startsWith('0')) value='0'+value; if(!/^0[0-9]{8,10}$/.test(value)) throw Object.assign(new Error('رقم أرضي غير صالح. استخدم رقمًا مصريًا مثل 0225551111.'),{statusCode:400}); return value; }
function parseManualClientLink(raw: string) {
  const link=String(raw||'').trim();
  if(!link) throw Object.assign(new Error('رابط الكونفيج مطلوب'),{statusCode:400});
  if(link.startsWith('vless://')){ let u:URL; try{u=new URL(link)}catch{throw Object.assign(new Error('رابط VLESS غير صالح'),{statusCode:400})}; const uuid=decodeURIComponent(u.username||''); const port=Number(u.port); if(!uuid||!u.hostname||!Number.isInteger(port)||port<1||port>65535) throw Object.assign(new Error('رابط VLESS غير مكتمل'),{statusCode:400}); const params:any={}; for(const k of ['type','security','sni','host','path','flow','fp','alpn','serviceName']) if(u.searchParams.get(k)) params[k]=u.searchParams.get(k); return {protocol:'vless',uuid,address:u.hostname,port,transport:params.type||'tcp',security:params.security||'none',params}; }
  if(link.startsWith('vmess://')){ try{ const enc=link.slice(8).replace(/-/g,'+').replace(/_/g,'/'); const pad=enc+'='.repeat((4-enc.length%4)%4); const o=JSON.parse(Buffer.from(pad,'base64').toString('utf8')); const uuid=String(o.id||o.uuid||''),address=String(o.add||o.address||''),port=Number(o.port); if(!uuid||!address||!Number.isInteger(port)||port<1||port>65535) throw new Error('bad'); const params:any={}; for(const k of ['host','path','sni','flow','fp','alpn','serviceName']) if(o[k]) params[k]=o[k]; return {protocol:'vmess',uuid,address,port,transport:String(o.net||'tcp'),security:o.tls?'tls':'none',params}; }catch{throw Object.assign(new Error('رابط VMess غير صالح'),{statusCode:400})} }
  throw Object.assign(new Error('الرابط يجب أن يبدأ بـ vless:// أو vmess://'),{statusCode:400});
}


app.register(cors, { origin: WEB_ORIGIN, credentials: true });
app.register(cookie);
app.register(rateLimit, { max: 120, timeWindow: '1 minute' });
app.addHook('preHandler', authenticate);
app.addHook('preHandler', async (req: Req) => {
  if (req.method !== 'POST' || !req.url.includes('/api/v1/admin/servers')) return;
  const body = (req.body || {}) as any;
  if (typeof body.address !== 'string') return;
  const address = body.address.trim();
  if (!address || address.includes('://') || (address.includes(':') && !/^\[[0-9a-fA-F:]+\]$/.test(address))) {
    throw Object.assign(new Error('عنوان الخادم يجب أن يكون IP أو hostname فقط. بورت Marzban موجود داخل الـProvider.'), { statusCode: 400 });
  }
  body.address = address;
});
app.setErrorHandler((error: any, _req, reply) => reply.code(errorStatus(error)).send({ error: error.message || 'Internal error' }));

