      await audit(c,req,'payment.confirmed','payments',p.id,{gateway:p.gateway,method:p.method,amountMinor:Number(p.amount_minor),orderCode:p.order_code},p.customer_id);
      await c.query('COMMIT');
      return pay.rows[0];
