app.post('/api/v1/webhooks/payments/:gateway', async (req:any) => { const signature=req.headers['x-webhook-signature'];const secret=process.env[`WEBHOOK_SECRET_${String(req.params.gateway).toUpperCase()}`];if(secret&&signature!==crypto.createHmac('sha256',secret).update(JSON.stringify(req.body)).digest('hex'))throw Object.assign(new Error('Invalid signature'),{statusCode:401});const eventId=String(req.headers['x-event-id']||req.body?.id||'');if(!eventId)throw Object.assign(new Error('Missing event id'),{statusCode:400});const c=await pool.connect();try{await c.query('BEGIN');const e=await c.query('INSERT INTO payment_events(gateway,event_id,payload) VALUES($1,$2,$3) ON CONFLICT(gateway,event_id) DO NOTHING RETURNING id',[req.params.gateway,eventId,req.body||{}]);if(!e.rowCount){await c.query('ROLLBACK');return {ok:true,duplicate:true};}const paymentId=req.body?.paymentId||req.body?.payment_id;const status=req.body?.status==='succeeded'?'SUCCEEDED':'FAILED';if(paymentId){await c.query('UPDATE payments SET status=$1,paid_at=CASE WHEN $1=\'SUCCEEDED\' THEN now() ELSE paid_at END,updated_at=now() WHERE id=$2',[status,paymentId]);if(status==='SUCCEEDED'){const o=await c.query(`UPDATE orders SET status='PAID',paid_at=now(),updated_at=now() WHERE id=(SELECT order_id FROM payments WHERE id=$1) RETURNING id`,[paymentId]);if(o.rowCount)await c.query(`INSERT INTO jobs(type,key,subject_type,subject_id,payload) VALUES('fulfill_order',$1,'ORDER',$2,$3) ON CONFLICT(key) DO NOTHING`,[`fulfill:${o.rows[0].id}`,o.rows[0].id,JSON.stringify({orderId:o.rows[0].id})]);}}await c.query('UPDATE payment_events SET payment_id=$1,processed_at=now(),result=$2 WHERE id=$3',[paymentId,status,e.rows[0].id]);await c.query('COMMIT');return {ok:true};}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}});

